	@Test
	void hardSemanticAndServingGuardsReplanBeforeUse() {
		LmdbPlanDecisionCache cache = new LmdbPlanDecisionCache(8, 1024 * 1024L);
		Fixture fixture = fixture(1L);
		assertTrue(cache.publishBuild(fixture.publication(fixture.evidence())));

		// Serving guards leave the retained version intact ...
		assertReplan(cache.lookupExact(fixture.exactKey(), new LmdbPlanDecisionCache.LookupRequest(
				fixture.dependencies(), fixture.evidence(), LmdbPlanDecisionCache.InvocationFeatures.empty(), 0.01d,
				false, false, false)), "executable-recipe-incompatible");
		assertReplan(cache.lookupExact(fixture.exactKey(), new LmdbPlanDecisionCache.LookupRequest(
				fixture.dependencies(), fixture.evidence(), LmdbPlanDecisionCache.InvocationFeatures.empty(), 0.01d,
				true, true, false)), "lifecycle-blocked");
		assertReplan(cache.lookupExact(fixture.exactKey(), new LmdbPlanDecisionCache.LookupRequest(
				fixture.dependencies(), fixture.evidence(), LmdbPlanDecisionCache.InvocationFeatures.empty(), 0.01d,
				true, false, true)), "resource-guard-violated");
		assertInstanceOf(LmdbPlanDecisionCache.Use.class,
				cache.lookupExact(fixture.exactKey(), fixture.request(fixture.evidence())));

		// ... whereas a hard semantic mismatch retires it: the stale version can never match the advanced
		// generation again, and retiring it lets the plan built for the current dependencies be published.
		LmdbPlanDecisionCache.SemanticDependencies changedCapability = new LmdbPlanDecisionCache.SemanticDependencies(
				"dataset", "bindings", "unordered", "standard", 1L, 2L, 1L, 1L, 1L, "config", "provider");
		assertReplan(cache.lookupExact(fixture.exactKey(), new LmdbPlanDecisionCache.LookupRequest(
				changedCapability, fixture.evidence(), LmdbPlanDecisionCache.InvocationFeatures.empty(), 0.01d,
				true, false, false)), "semantic-dependency-mismatch");
		assertReplan(cache.lookupExact(fixture.exactKey(), fixture.request(fixture.evidence())),
				"hard-dependency-invalid");
	}

