	@Test
	void guardedCanaryIsDeterministicAndCensoredEvidenceStopsOnlyThatChallenger() throws Exception {
		LmdbPlanDecisionCache cache = canaryCache(0.01d);
		Fixture fixture = fixture(1L);
		assertTrue(cache.publishBuild(buildPublication(fixture, "champion", 100.0d)));
		long version = familyVersion(cache, fixture, 1.0d);
		assertTrue(cache.publishRefresh(refreshPublication(fixture, version, "safe-challenger", 100.5d, false)));

		LmdbPlanDecisionCache.LookupRequest canaryRequest = withCanary(fixture.request(fixture.evidence()), 71L, 0L);
		LmdbPlanDecisionCache.Use canary = assertInstanceOf(LmdbPlanDecisionCache.Use.class,
				cache.lookupFamily(fixture.familyKey(), canaryRequest));
		assertTrue(isCanary(canary));
		assertEquals("safe-challenger", canary.plan().physicalFingerprint());
		assertEquals(LmdbPlanDecisionCache.DeploymentRole.CHALLENGER, canary.plan().deploymentRole());
		assertEquals(canary.plan().version(), assertInstanceOf(LmdbPlanDecisionCache.Use.class,
				cache.lookupFamily(fixture.familyKey(), canaryRequest)).plan().version());

		LmdbPlanDecisionCache.Use outsideSample = assertInstanceOf(LmdbPlanDecisionCache.Use.class,
				cache.lookupFamily(fixture.familyKey(),
						withCanary(fixture.request(fixture.evidence()), 71L, Long.MAX_VALUE)));
		assertFalse(isCanary(outsideSample));
		assertEquals("champion", outsideSample.plan().physicalFingerprint());

		cache.observeExecution(new LmdbPlanDecisionCache.ExecutionObservation(fixture.familyKey(), canary.variantId(),
				canary.plan().version(), false, true, 2.0d, 512L, false, false));
		LmdbPlanDecisionCache.PlanVariant currentVariant = currentFamilyVersion(cache, fixture.familyKey())
				.dispatcher()
				.variants()
				.get(0);
		LmdbPlanDecisionCache.RuntimePosterior challengerPosterior = posteriorFor(currentVariant,
				canary.plan().version());
		assertEquals(0L, challengerPosterior.completeObservations());
		assertEquals(1L, challengerPosterior.censoredObservations());

		LmdbPlanDecisionCache.Use afterCensor = assertInstanceOf(LmdbPlanDecisionCache.Use.class,
				cache.lookupFamily(fixture.familyKey(), canaryRequest));
		assertFalse(isCanary(afterCensor));
		assertEquals("champion", afterCensor.plan().physicalFingerprint());
	}

