	private static boolean publishVariant(LmdbPlanDecisionCache cache, Fixture fixture, long expectedVersion,
			long variantId, LmdbPlanDecisionCache.ApplicabilityGuard guard, String fingerprint, double cost)
			throws Exception {
		Method method = Arrays.stream(LmdbPlanDecisionCache.class.getDeclaredMethods())
				.filter(candidate -> candidate.getName().equals("publishVariant"))
				.findFirst()
				.orElseThrow();
		Class<?> publicationType = method.getParameterTypes()[0];
		Constructor<?> constructor = publicationType.getDeclaredConstructors()[0];
		Object publication = constructor.newInstance(fixture.familyKey(), expectedVersion, fixture.dependencies(),
				fixture.evidence(), fixture.evidence(), variantId, guard, fixture.template(), fingerprint,
				new LmdbPlanDecisionCache.EstimatedCostInterval(cost, cost),
				new LmdbPlanDecisionCache.SearchCertificate(LmdbPlanDecisionCache.SearchCompletion.EXACT_COMPLETE,
						LmdbPlanDecisionCache.BoundKind.BEST_KNOWN_UNBOUNDED, Double.NaN,
						fixture.evidence().globalEpoch(), fixture.evidence().globalEpoch(), 0.0d, 10L),
				new LmdbPlanDecisionCache.PlanStabilityEnvelope(fixture.evidence(),
						guard.minimumCardinalities(), guard.maximumCardinalities(), true),
				256L, 1L);
		return (boolean) method.invoke(cache, publication);
	}

	private static void assertUseFingerprint(LmdbPlanDecisionCache.LookupDecision decision, String fingerprint,
			long variantId) {
		LmdbPlanDecisionCache.Use use = assertInstanceOf(LmdbPlanDecisionCache.Use.class, decision);
		assertEquals(fingerprint, use.plan().physicalFingerprint());
		assertEquals(variantId, use.variantId());
	}

	private static void assertReplan(LmdbPlanDecisionCache.LookupDecision decision, String reason) {
		LmdbPlanDecisionCache.ReplanBeforeUse replan = assertInstanceOf(
				LmdbPlanDecisionCache.ReplanBeforeUse.class, decision);
		assertEquals(LmdbPlanDecisionCache.LookupOutcome.REPLAN_BEFORE_USE, replan.outcome());
		assertEquals(reason, replan.reason());
	}

